//! Userspace side of the BPF programs in this directory (`main.bpf.c`).
//!
//! - this file: checking the kernel has the hooks bpfrag needs, and small
//!   helpers shared by the submodules;
//! - [`maps`]: reading and writing the BPF maps;
//! - [`tc`]: attaching the DSCP marker and the arrival meter to interfaces.
//!
//! The skeleton itself (`BpfSkel`) is generated by build.rs into
//! `crate::bpf_skel`, and the C structs shared through `intf.h` are
//! bindgen'd into `crate::bpf_intf`, the same split the sched_ext Rust
//! schedulers use.

pub mod maps;
pub mod tc;

use anyhow::{Context, Result, bail};
use libbpf_rs::btf::{Btf, BtfType};
use log::debug;

/// The oldest kernel bpfrag runs on, for messages.
pub const MIN_KERNEL: &str = "6.6";

fn btf_has(btf: &Btf, name: &str) -> bool {
    btf.type_by_name::<BtfType>(name).is_some()
}

/// Does this kernel have what bpfrag needs? Decided from the kernel's own
/// BTF rather than its version, so backports count: the generic socket
/// tracepoints that count UDP per process (6.4, `btf_trace_*` types) and
/// tcx links for the tc programs (6.6, `struct tcx_entry`).
pub fn check_kernel() -> Result<()> {
    let btf = Btf::from_vmlinux().context("kernel BTF (/sys/kernel/btf/vmlinux) is required")?;
    let tracepoints =
        btf_has(&btf, "btf_trace_sock_send_length") && btf_has(&btf, "btf_trace_sock_recv_length");
    if !tracepoints {
        bail!(
            "this kernel has no sock_send_length/sock_recv_length tracepoints (needs {MIN_KERNEL}+)"
        );
    }
    if !btf_has(&btf, "tcx_entry") {
        bail!("this kernel has no tcx links (needs {MIN_KERNEL}+)");
    }
    debug!("kernel has the socket tracepoints and tcx");
    Ok(())
}

/// Copy a map key or value into a bindgen'd struct.
///
/// Only for plain-old-data types made of integers (everything in intf.h),
/// where any byte pattern is a valid value. Short input leaves the rest at
/// its default.
fn from_bytes<T: Copy + Default>(b: &[u8]) -> T {
    let mut v = T::default();
    if b.len() >= size_of::<T>() {
        unsafe {
            std::ptr::copy_nonoverlapping(
                b.as_ptr(),
                (&mut v as *mut T).cast::<u8>(),
                size_of::<T>(),
            )
        };
    }
    v
}

/// Raise RLIMIT_MEMLOCK so maps can be created. Only matters on kernels
/// before 5.11, which charged BPF memory to it (newer ones use memcg).
pub fn bump_memlock() {
    let rl = libc::rlimit {
        rlim_cur: libc::RLIM_INFINITY,
        rlim_max: libc::RLIM_INFINITY,
    };
    if unsafe { libc::setrlimit(libc::RLIMIT_MEMLOCK, &rl) } != 0 {
        debug!(
            "could not raise RLIMIT_MEMLOCK: {}",
            std::io::Error::last_os_error()
        );
    }
}
